# Keep repeated patient schedule text consistent across chapters and logistics.
def revise_route_text(z):
 if isinstance(z,str):
  return z.replace('IV trastuzumab every 21 days','trastuzumab every 21 days by the agreed IV or locally approved SC route').replace('IV treatment every three weeks with staff observation. A cannula, PICC or port may be used;', 'Trastuzumab every three weeks with staff observation. IV treatment may use a cannula, PICC or port; the locally approved SC alternative uses an injection under the skin;')
 if isinstance(z,list):return [revise_route_text(a) for a in z]
 if isinstance(z,dict):return {k:revise_route_text(v) for k,v in z.items()}
 return z
